// ---- the inactivity rule (SPEC 13 §10, SPEC 13d §4.4) ----

/** After 60 days without opening the app, a live provider's services pause; the warning goes out 7 days before. */
export const INACTIVITY = { pauseAfterDays: 60, warnBeforeDays: 7 } as const;

/** The Manila day the inactivity pause is due, from the last activity (null: no activity recorded yet). */
export function inactivityPausesOn(lastActiveAt: Date | string | null): string | null {
  if (lastActiveAt === null) return null;
  const at = typeof lastActiveAt === "string" ? new Date(lastActiveAt) : lastActiveAt;
  if (Number.isNaN(at.getTime())) return null;
  return addDays(manilaDate(at), INACTIVITY.pauseAfterDays);
}

// ---- handle (SPEC 13d G11) ----

const HANDLE = /^[a-z][a-z0-9._]*$/;
/** Staff words a handle may not start or end with, even run together with other letters ("adminjuan", "supportph"). */
const HANDLE_STAFF_EDGES = ["admin", "support", "staff", "moderator", "official"];

/** Why a handle is refused (user-ready), or null. `s` is already lower case and trimmed. */
export function handleProblem(s: string): string | null {
  if (s.length < LIMITS.handle.min || s.length > LIMITS.handle.max) return `Use ${LIMITS.handle.min} to ${LIMITS.handle.max} characters.`;
  if (!HANDLE.test(s)) return "Use letters, numbers, dots or underscores, starting with a letter.";
  if (s.includes("..") || /[._]$/.test(s)) return "Don't end with a dot or underscore, or use two dots in a row.";
  const team = "Choose a handle that doesn't use the Phriend name or sound like Phriend's team.";
  if (reservedNameProblem(s.replace(/[._]/g, " "), "display_name")) return team;
  const letters = s.replace(/[^a-z]/g, "");
  if (HANDLE_STAFF_EDGES.some((w) => letters.startsWith(w) || letters.endsWith(w))) return team;
  return null;
}

/** Handle changes (security review M4): one change per 30 days after the first; a released handle stays reserved 30 days. */
export const HANDLE_POLICY = { changeEveryDays: 30, reserveDays: 30 } as const;

/** When the provider may change their handle again (null: now). `lastChangedAt` is their last own change. */
export function handleChangeAllowedAt(lastChangedAt: Date | string | null, now: Date = new Date()): Date | null {
  if (lastChangedAt === null) return null;
  const at = new Date(new Date(lastChangedAt).getTime() + HANDLE_POLICY.changeEveryDays * 86_400_000);
  return at > now ? at : null;
}

/**
 * Handle candidates from the display name ("Ana Dela Cruz" → anadelacruz, ana.dela.cruz, anadelacruz4821, ...), each
 * one passing `handleProblem` (a name like "Admin Juan" gets `pro…` candidates instead).
 */
export function handleCandidates(displayName: string, random: () => number = Math.random): string[] {
  const max = LIMITS.handle.max;
  const words = displayName
    .normalize("NFKD")
    .replace(/[̀-ͯ]/g, "")
    .toLowerCase()
    .split(/[^a-z0-9]+/)
    .filter(Boolean);
  let joined = words.join("").replace(/^[0-9]+/, "");
  let dotted = words.join(".").replace(/^[0-9.]+/, "");
  if (joined.length < 3) joined = `pro${joined}`;
  if (dotted.length < 3) dotted = joined;
  joined = joined.slice(0, max - 5);
  dotted = dotted.slice(0, max).replace(/[._]+$/, "");
  const digits = () => String(Math.floor(1000 + random() * 9000));
  const out = new Set<string>();
  for (const base of [joined, dotted]) if (!handleProblem(base)) out.add(base);
  for (let i = 0; i < 6; i++) {
    const c = `${joined}${digits()}`;
    out.add(handleProblem(c) ? `pro${digits()}${digits()}` : c);
  }
  return [...out];
}

/** 3-30 of `a-z 0-9 . _`, starting with a letter; case-insensitive (stored lower case). */
export const handleSchema = z
  .string({ error: "Enter a handle." })
  .transform((s) => s.trim().toLowerCase())
  .superRefine((s, ctx) => {
    const problem = handleProblem(s);
    if (problem) ctx.addIssue({ code: "custom", message: problem });
  });

