const versionField = z.number({ error: "This is required." }).int().min(1);

/**
 * `PATCH /v1/provider/profile`: the fields that change, and `version`. `languages` is one field (the whole list,
 * 1-8 codes, in order); `about: null` clears it; `avatarMediaId` is an `avatar` upload of this provider (null removes it).
 */
export const patchProviderProfileBodySchema = z
  .strictObject({
    displayName: listingText(LIMITS.displayName, { noEmoji: true, reserved: "display_name" }).optional(),
    title: listingText(LIMITS.providerTitle, { noEmoji: true, reserved: "title" }).optional(),
    about: optionalListingText(LIMITS.about, { multiline: true, noEmoji: true }).optional(),
    baseCityId: z.number({ error: "Pick a city." }).int("Pick a city.").positive("Pick a city.").optional(),
    languages: z
      .array(z.string({ error: "Pick a language." }).min(1).max(8), { error: "Pick your languages." })
      .min(CAPS.languagesMin, "Pick at least one language.")
      .max(CAPS.languagesMax, `Pick up to ${CAPS.languagesMax} languages.`)
      .refine((l) => new Set(l).size === l.length, "Pick each language once.")
      .optional(),
    handle: handleSchema.optional(),
    avatarMediaId: uuidSchema.nullable().optional(),
    version: versionField,
  })
  .refine((b) => Object.keys(b).some((k) => k !== "version"), { message: "Change at least one field.", path: ["_form"] });
export type PatchProviderProfileBody = z.output<typeof patchProviderProfileBodySchema>;

