export const putTimeOffBodySchema = z.strictObject({ note: optionalText(LIMITS.timeOffNote, { noEmoji: true }).optional() }).optional();
export type PutTimeOffBody = z.output<typeof putTimeOffBodySchema>;

/** Why a day off is refused (user-ready), or null: a real day, today to 365 days ahead (Manila). */
export function timeOffDayProblem(day: string, today: string): string | null {
  if (!isManilaDay(day)) return "Pick a date.";
  if (day < today) return "Pick today or a later date.";
  if (day > addDays(today, CAPS.timeOffDaysAhead)) return `Pick a date within ${CAPS.timeOffDaysAhead} days.`;
  return null;
}

